import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # limit[l][x]: smallest right endpoint of a condition targeting x
    # whose left endpoint is at least l. Endpoints on the right are exclusive.
    limit = [[n + 1] * n for _ in range(n + 1)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i + 3]
        if l == r:
            print(0)
            return
        l -= 1
        x -= 1
        if r < limit[l][x]:
            limit[l][x] = r

    for l in range(n - 1, -1, -1):
        row = limit[l]
        nxt = limit[l + 1]
        for k in range(n):
            if nxt[k] < row[k]:
                row[k] = nxt[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid-order count on [l,r), divided by (r-l)!.
    # Keep a transposed copy for efficient access to both child intervals.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    col = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = col[i][i] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        lim = limit[l]
        for r in range(l + 1, n + 1):
            right = col[r]
            total = 0
            for k in range(l, r):
                if lim[k] > r:
                    total += row[k] * right[k + 1]
            value = total * inv[r - l] % MOD
            row[r] = right[l] = value

    answer = dp[0][n]
    for i in range(1, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    solve()

