import sys
from collections import deque

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n

    while q:
        u = q.popleft()
        v = a[u]
        b, c = dp[u], dp[v]
        if b is None:
            if c is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    c[j] = c[j] * (j + 1) % MOD
        elif c is None:
            s = 0
            for j in range(m):
                s = (s + b[j]) % MOD
                b[j] = s
            dp[v] = b
        else:
            s = 0
            for j in range(m):
                s = (s + b[j]) % MOD
                c[j] = c[j] * s % MOD
        dp[u] = None
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)

    ans = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        u = i
        product = None
        while deg[u]:
            deg[u] = 0
            b = dp[u]
            if b is not None:
                if product is None:
                    product = b
                else:
                    for j in range(m):
                        product[j] = product[j] * b[j] % MOD
            dp[u] = None
            u = a[u]
        ways = m if product is None else sum(product) % MOD
        ans = ans * ways % MOD
    print(ans)

if __name__ == '__main__':
    solve()

