import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for j, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][j] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][j] = 1

    answer = 1
    for p, exponents in factors.items():
        limit = max(sum(exponents), n * max(exponents))
        powers = [1] * (limit + 1)
        for k in range(1, limit + 1):
            powers[k] = powers[k - 1] * p % MOD

        # Prefix exponent paths are normalized to have minimum zero.
        # The state is the last exponent; its weight is the prefix score.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                for h in range(len(dp)):
                    dp[h] = dp[h] * powers[h] % MOD
                continue

            new_dp = [0] * (len(dp) + e)
            for h, value in enumerate(dp):
                up = h + e
                new_dp[up] = (new_dp[up] + value * powers[up]) % MOD
                if h >= e:
                    down = h - e
                    new_dp[down] = (new_dp[down] + value * powers[down]) % MOD
                else:
                    # A new minimum shifts all i preceding exponents upward.
                    new_dp[0] = (new_dp[0] + value * powers[i * (e - h)]) % MOD
            dp = new_dp
        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    solve()

