import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    limit = max(a)

    # omega[x] counts prime factors of x, including multiplicity.
    # This is the Grundy number of a single integer x.
    omega = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if omega[p] == 0:
            power = p
            while power <= limit:
                for multiple in range(power, limit + 1, power):
                    omega[multiple] += 1
                power *= p

    nim_sum = 0
    for x in a:
        nim_sum ^= omega[x]
    print('Anna' if nim_sum else 'Bruno')


