import sys


def solve():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(data)
    m = next(data)
    q = next(data)
    edges = [(next(data) - 1, next(data) - 1, next(data)) for _ in range(m)]
    queries = []
    closed = bytearray(m)
    for _ in range(q):
        t = next(data)
        if t == 1:
            e = next(data) - 1
            closed[e] = 1
            queries.append((1, e))
        else:
            queries.append((2, next(data) - 1, next(data) - 1))

    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = w

    r = range(n)
    for k in r:
        dk = d[k]
        for i in r:
            di = d[i]
            base = di[k]
            if base == inf:
                continue
            for j in r:
                v = base + dk[j]
                if v < di[j]:
                    di[j] = v

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            v = d[query[1]][query[2]]
            ans.append(str(v if v < inf else -1))
        else:
            a, b, w = edges[query[1]]
            if d[a][b] <= w:
                continue
            da = d[a][:]
            db = d[b][:]
            for i in r:
                if da[i] + w < db[i]:
                    base = da[i] + w
                    src = db
                elif db[i] + w < da[i]:
                    base = db[i] + w
                    src = da
                else:
                    continue
                di = d[i]
                for j in r:
                    v = base + src[j]
                    if v < di[j]:
                        di[j] = v

    sys.stdout.write('\n'.join(reversed(ans)))


if __name__ == '__main__':
    solve()

