import sys
import heapq


def solve_case(n, m, boxes):
    if n < m:
        return 0
    if m == 1:
        return sum(v - p for v, p in boxes if v > p)

    boxes.sort(reverse=True)
    k = m - 1
    remaining = sum(v - p for v, p in boxes if v > p)
    heap = []
    cost = 0
    answer = 0
    for v, p in boxes:
        if v > p:
            remaining -= v - p
        if len(heap) < k:
            heapq.heappush(heap, -p)
            cost += p - 1
        elif p < -heap[0]:
            old = -heapq.heapreplace(heap, -p)
            cost += p - old
        if len(heap) == k:
            candidate = remaining - cost
            if candidate > answer:
                answer = candidate
    return answer


def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    t = next(data)
    output = []
    for _ in range(t):
        n = next(data)
        m = next(data)
        boxes = [(next(data), next(data)) for _ in range(n)]
        output.append(str(solve_case(n, m, boxes)))
    sys.stdout.write('\n'.join(output))


if __name__ == '__main__':
    main()

