import sys


def solve(a):
    # Return the best score for an even and an odd starting position.
    if len(a) <= 1:
        return len(a), len(a)

    even = []
    odd = []
    e0 = e1 = o0 = o1 = 0
    for x in a:
        if x & 1:
            odd.append((x + 1) >> 1)
            if x & 2:
                o1 += 1
            else:
                o0 += 1
        else:
            even.append(x >> 1)
            if x & 2:
                e1 += 1
            else:
                e0 += 1

    p, q = solve(even)
    r, s = solve(odd)
    # A crease is a mountain precisely when its odd part is 3 modulo 4.
    return max(p + o1, q + o0), max(r + e1, s + e0)


