from math import isqrt


def solve(n):
    # Let d = x - y. Then n/d = 3*y*y + 3*d*y + d*d.
    for d in range(1, 1000001):
        d2 = d * d
        if d2 * d >= n:
            break
        if n % d:
            continue
        discriminant = 12 * (n // d) - 3 * d2
        if discriminant <= 0:
            continue
        s = isqrt(discriminant)
        if s * s == discriminant and s > 3 * d and (s - 3 * d) % 6 == 0:
            y = (s - 3 * d) // 6
            return y + d, y
    return None


def main():
    n = int(sys.stdin.buffer.read())
    answer = solve(n)
    if answer is None:
        print(-1)
    else:
        print(*answer)


