from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [
            powers[i] if i == n - 1 - i
            else (powers[i] + powers[n - 1 - i]) % k
            for i in range(m)
        ]

        # Digits 0..9 include every residue modulo k. Thus the
        # attainable suffix residues are exactly multiples of this gcd.
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        half = []
        remainder = 0
        for i, weight in enumerate(weights):
            for digit in range(9, 0 if i == 0 else -1, -1):
                candidate = (remainder + digit * weight) % k
                if candidate % suffix[i + 1] == 0:
                    half.append(str(digit))
                    remainder = candidate
                    break

        left = ''.join(half)
        return left + (left[:-1] if n % 2 else left)[::-1]

