from functools import cmp_to_key


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    k = next(it)

    counts = {}
    for _ in range(n):
        a = next(it)
        b = next(it)
        counts[a, b] = min(k, counts.get((a, b), 0) + 1)

    # Apply inner functions first, in increasing order of (a - 1) / b.
    def compare(x, y):
        return (x[0] - 1) * y[1] - (y[0] - 1) * x[1]

    items = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0

    for a, b in items:
        for _ in range(counts[a, b]):
            seen += 1
            for j in range(min(k, seen), 0, -1):
                if dp[j - 1] >= 0:
                    value = dp[j - 1] * a + b
                    if value > dp[j]:
                        dp[j] = value

    print(dp[k])


