def solve(h, w, rows):
    parent = [-1] * (h + w)
    parity = bytearray(h + w)
    col_prefix = bytearray(w)
    components = h + w

    def find(x):
        value = 0
        while parent[x] >= 0:
            p = parent[x]
            value ^= parity[x]
            if parent[p] >= 0:
                parity[x] ^= parity[p]
                parent[x] = parent[p]
            x = p
        return x, value

    for i, row in enumerate(rows):
        row_prefix = 0
        for j, ch in enumerate(row):
            if ch == 65:
                row_prefix ^= 1
                col_prefix[j] ^= 1
            else:
                a, va = find(i)
                b, vb = find(h + j)
                z = 1 ^ row_prefix ^ col_prefix[j] ^ va ^ vb
                if a == b:
                    if z:
                        return 0
                else:
                    if parent[a] > parent[b]:
                        a, b = b, a
                    parent[a] += parent[b]
                    parent[b] = a
                    parity[b] = z
                    components -= 1
        if row_prefix:
            return 0

    if any(col_prefix):
        return 0
    return pow(2, components, MOD)


