import sys

def possible(s,t,k):
    n,m=len(s),len(t)
    if abs(n-m)>k:
        return False
    off=k+1
    prev=[-1]*(2*k+3)
    x=0
    while x<n and x<m and s[x]==t[x]:
        x+=1
    if x==n and x==m:
        return True
    prev[off]=x
    for e in range(1,k+1):
        cur=[-1]*(2*k+3)
        for d in range(max(-e,-m),min(e,n)+1):
            j=off+d
            a=prev[j]
            x=a
            if a>=0 and a<n and a-d<m:
                x=a+1
            a=prev[j-1]
            if a>=0 and a<n and a+1>x:
                x=a+1
            a=prev[j+1]
            if a>=0 and a-(d+1)<m and a>x:
                x=a
            if x<0:
                continue
            y=x-d
            while x<n and y<m and s[x]==t[y]:
                x+=1
                y+=1
            if x==n and y==m:
                return True
            cur[j]=x
        prev=cur
    return False

