from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Each subtree occupies one interval in the global postorder string.
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                start[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                order.append(s[x])
                end[x] = len(order)

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and order[i-k] == order[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and order[i-k-1] == order[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = []
        for a, b in zip(start, end):
            length = b - a
            mid = (a + b) // 2
            if length % 2:
                answer.append(odd[mid] >= length // 2 + 1)
            else:
                answer.append(even[mid] >= length // 2)
        return answer

