import sys
import heapq


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    s = next(it) - 1
    t = next(it) - 1
    g = [[] for _ in range(n)]
    for _ in range(m):
        u = next(it) - 1
        v = next(it) - 1
        g[u].append(v)
        g[v].append(u)

    dist = [-1] * n
    parent = [-1] * n
    dist[s] = 0
    queue = [s]
    for u in queue:
        for v in g[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                parent[v] = u
                queue.append(v)

    path = []
    u = t
    while u != -1:
        path.append(u)
        u = parent[u]
    path.reverse()
    d = len(path) - 1
    index = [-1] * n
    for i, u in enumerate(path):
        index[u] = i

    # Distance to the fixed shortest path.
    near = [-1] * n
    queue = path[:]
    for u in path:
        near[u] = 0
    for u in queue:
        for v in g[u]:
            if near[v] == -1:
                near[v] = near[u] + 1
                queue.append(v)

    inf = 10**9
    answer = inf
    # Passing by means of a branching vertex.
    for u in range(n):
        if len(g[u]) >= 3:
            if 0 < index[u] < d:
                answer = min(answer, 2 * d + 2)
            else:
                answer = min(answer, 2 * d + 4 * near[u] + 4)

    # Find bypasses between distinct vertices of the path. For each
    # off-path vertex retain the two best distinct source labels.
    heap = [(i, u, i) for i, u in enumerate(path)]
    heapq.heapify(heap)
    first = [-1] * n
    second = [-1] * n
    while heap:
        cost, u, source = heapq.heappop(heap)
        if first[u] == source or second[u] != -1:
            continue
        if first[u] == -1:
            first[u] = source
        else:
            second[u] = source
        for v in g[u]:
            if index[v] != -1:
                if index[u] == -1 and index[v] != source:
                    answer = min(answer, 2 * d + cost + 1 - index[v])
            elif first[v] != source and second[v] == -1:
                heapq.heappush(heap, (cost + 1, v, source))

    print(answer if answer != inf else -1)


if __name__ == '__main__':
    main()

