class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        minima = [float('inf')] * k
        minima[0] = 0
        prefix = 0
        answer = -float('inf')

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k
            candidate = prefix - minima[remainder]
            if candidate > answer:
                answer = candidate
            if prefix < minima[remainder]:
                minima[remainder] = prefix

        return answer

