    def dfs(u, seen, length):
        nonlocal best
        for v in adj[u]:
            if v == 0:
                best = min(best, length+1)
            elif v not in seen:
                dfs(v, seen | {v}, length+1)
    dfs(0, {0}, 0)
    return best if best <= n else -1

