class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s records whether a subset of the processed values sums to s.
        reachable = [1] * n
        masks = [(1 << (target + 1)) - 1 for target in nums]
        pending = [target != 0 for target in nums]
        remaining = sum(pending)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if pending[i]:
                    reachable[i] = (reachable[i] | (reachable[i] << value)) & masks[i]
                    if (reachable[i] >> nums[i]) & 1:
                        pending[i] = False
                        remaining -= 1
            if remaining == 0:
                return k
        return -1

