from heapq import heappush, heappop
from math import isqrt

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits
        lower = limit // 10
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, isqrt(limit - 1) + 1):
            if prime[p]:
                start = p * p
                prime[start:limit:p] = b'\x00' * ((limit - 1 - start) // p + 1)
        if prime[n] or prime[m]:
            return -1

        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]
        while heap:
            cost, x = heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in powers:
                digit = x // p % 10
                if digit < 9:
                    y = x + p
                    new = cost + y
                    if not prime[y] and new < dist[y]:
                        dist[y] = new
                        heappush(heap, (new, y))
                if digit > 0:
                    y = x - p
                    new = cost + y
                    if y >= lower and not prime[y] and new < dist[y]:
                        dist[y] = new
                        heappush(heap, (new, y))
        return -1

