from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        a = bytes(nums)
        n = len(a)
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k + 1, z[k - left]) if k <= right else 0
            while k + v < n and a[v] == a[k + v]:
                v += 1
            z[k] = v
            if k + v - 1 > right:
                left, right = k, k + v - 1

        answer = 0
        for i in range(1, n - 1):
            limit = (n - i) // 2
            if z[i] >= i:
                # All second pieces of length at least i satisfy condition one.
                answer += n - 2 * i
                limit = min(limit, i - 1)
            if not limit:
                continue

            # Check condition two only where it has not already been counted.
            s = a[i:]
            m = len(s)
            local = [0] * (limit + 1)
            left = right = 0
            for k in range(1, limit + 1):
                v = min(right - k + 1, local[k - left]) if k <= right else 0
                while k + v < m and s[v] == s[k + v]:
                    v += 1
                local[k] = v
                if v >= k:
                    answer += 1
                if k + v - 1 > right:
                    left, right = k, k + v - 1
        return answer

