class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        # dp[j] is the minimum number of target indices needed to
        # form the first j characters of pattern from the processed source.
        positions = [[] for _ in range(26)]
        for j in range(len(pattern) - 1, -1, -1):
            positions[ord(pattern[j]) - 97].append(j)

        removable = set(targetIndices)
        dp = [0] + [len(source) + 1] * len(pattern)
        for i, ch in enumerate(source):
            cost = int(i in removable)
            # Descending order prevents using this source character twice.
            for j in positions[ord(ch) - 97]:
                value = dp[j] + cost
                if value < dp[j + 1]:
                    dp[j + 1] = value

        return len(targetIndices) - dp[-1]

